  home: ['park', 'shop'],
  park: ['home', 'lake'],
  shop: ['home', 'school'],
  lake: ['park', 'school'],
  school: ['shop', 'lake'],
}

function stepsBetween(start, goal) {
  const queue = [[start, 0]]
  const seen = new Set([start])
  while (queue.length > 0) {
    const [node, steps] = queue.shift()
    if (node === goal) return steps
    for (const next of graph[node]) {
      if (!seen.has(next)) {
        seen.add(next)
        queue.push([next, steps + 1])
      }
    }
  }
  return -1
}
