from collections import deque

graph = {
    'home': ['park', 'shop'],
    'park': ['home', 'lake'],
    'shop': ['home', 'school'],
    'lake': ['park', 'school'],
    'school': ['shop', 'lake'],
}

def steps_between(start, goal):
    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        node, steps = queue.popleft()
        if node == goal:
            return steps
        for nxt in graph[node]:
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, steps + 1))
    return -1

print(steps_between('home', 'shop'), steps_between('home', 'school'))

