  '##..#',
  '#...#',
  '..#..',
  '.....',
]

function countIslands(rows) {
  const seen = new Set()
  function visit(r, c) {
    if (r < 0 || c < 0 || r >= rows.length || c >= rows[0].length) return
    const key = `${r},${c}`
    if (rows[r][c] !== '#' || seen.has(key)) return
    seen.add(key)
    visit(r + 1, c)
    visit(r - 1, c)
    visit(r, c + 1)
    visit(r, c - 1)
  }
  let islands = 0
  for (let r = 0; r < rows.length; r++) {
    for (let c = 0; c < rows[0].length; c++) {
      if (rows[r][c] === '#' && !seen.has(`${r},${c}`)) {
        islands++
        visit(r, c)
      }
    }
  }
  return islands
}
