world = [
    '##..#',
    '#...#',
    '..#..',
    '.....',
]

def count_islands(rows):
    seen = set()

    def visit(r, c):
        if r < 0 or c < 0 or r >= len(rows) or c >= len(rows[0]):
            return
        if rows[r][c] != '#' or (r, c) in seen:
            return
        seen.add((r, c))
        visit(r + 1, c)
        visit(r - 1, c)
        visit(r, c + 1)
        visit(r, c - 1)

    islands = 0
    for r in range(len(rows)):
        for c in range(len(rows[0])):
            if rows[r][c] == '#' and (r, c) not in seen:
                islands += 1
                visit(r, c)
    return islands

print(count_islands(world))
